  terms_updateemail: `<p><span style="text-decoration: underline;"><strong>Actualizaci&oacute;n de correo por la APP Mibanco.</strong></span></p>
  <p>&nbsp;</p>
  <p>El CLIENTE manifiesta su intenci&oacute;n de actualizar su correo electr&oacute;nico a trav&eacute;s de la app &ldquo;MIBANCO M&oacute;vil&rdquo; (en adelante, la &ldquo;APP&rdquo;).&nbsp;</p>
  <p>&nbsp;</p>
  <p>Te agradecemos por mantener tus datos actualizados y protegidos con nosotros. Brindarte un mejor servicio es uno de nuestros principales objetivos y para esto es importante contar con tus datos de contacto actualizados.&nbsp;</p>
  <p>&nbsp;</p>
  <p>Entre otras cosas, mantener tus datos actualizados te permitir&aacute;:&nbsp;</p>
  <ul>
  <li aria-level="1">Recibir las constancias de tus operaciones por correo.</li>
  <li aria-level="1">Recibir la documentaci&oacute;n en caso de contrataci&oacute;n de alg&uacute;n producto.</li>
  <li aria-level="1">Recibir oportunamente tus estados de cuenta.</li>
  <li aria-level="1">Recibir informaci&oacute;n sobre cualquier cambio en tus productos.</li>
  </ul>
  <p>&nbsp;</p>
  <p>El flujo para el cambio de correo es muy sencillo:</p>
  <ol>
  <li aria-level="1">Ingresas a &ldquo;Mi Perfil&rdquo; y das clic en &ldquo;Agregar&rdquo; o &ldquo;Cambiar&rdquo; (seg&uacute;n sea tu necesidad).</li>
  <li aria-level="1">Ingresas el nuevo correo electr&oacute;nico, repites para garantizar que est&eacute; correcto (deben coincidir).</li>
  <li aria-level="1">Ingresas el c&oacute;digo recibido por SMS a tu celular (c&oacute;digo OTP con una validez de m&aacute;x. 3min enviado al celular que tengas registrado en nuestro Sistema).</li>
  <li aria-level="1">Aceptas los t&eacute;rminos y condiciones.</li>
  <li aria-level="1">Aprietas: &iexcl;&ldquo;Agregar mi correo electr&oacute;nico&rdquo; o &ldquo;Cambiar mi correo electr&oacute;nico&rdquo; y listo!</li>
  <li aria-level="1">Como confirmaci&oacute;n de la actualizaci&oacute;n recibir&aacute;s un SMS a tu celular con el siguiente mensaje: &ldquo;Mibanco: Has registrado con &eacute;xito tu nuevo correo en Mibanco. Si no fuiste t&uacute;, comun&iacute;cate al (01) 319-9999&rdquo;.</li>
  </ol>
  <p><br /><br /><br /></p>
  <p>Consentimiento informado</p>
  <p>&nbsp;</p>
  <p>El correo electr&oacute;nico y dem&aacute;s datos personales declarados en este proceso ser&aacute;n almacenados en el "Banco de Datos Personales de Usuarios", registrado ante la Autoridad Nacional de Protecci&oacute;n de Datos Personales bajo el n&uacute;mero de registro RNPDP-PJP N&deg;332, de titularidad de Mibanco &ndash; Banco de la Microempresa S.A., domiciliado en Av. Rep&uacute;blica de Panam&aacute; 4575 &ndash; Piso 3, Surquillo, Lima. Mibanco podr&aacute; usar, procesar, transferir a las empresas del Grupo Credicorp, socios comerciales y/o terceros encargados que se indiquen en el tiempo en www.mibanco.com.pe y/o darles cualquier otra forma de tratamiento regulada por la Ley N&deg;29733 - Ley de Protecci&oacute;n de Datos Personales, su Reglamento y dem&aacute;s modificatorias hasta por diez (10) a&ntilde;os despu&eacute;s de finalizada la relaci&oacute;n contractual.&nbsp;</p>
  <p>&nbsp;</p>
  <p>El CLIENTE debe comunicar cualquier actualizaci&oacute;n de su informaci&oacute;n y puede acceder a sus datos, rectificarlos, oponerse a su uso o revocar el consentimiento en cualquiera de las agencias Mibanco a nivel nacional; siempre y cuando cumpla con los requisitos exigidos por la Ley.&nbsp;</p>
  <p>&nbsp;</p>
  <p>Para mayor informaci&oacute;n consultar la Pol&iacute;ticas de Privacidad y Protecci&oacute;n de datos publicada en www.mibanco.com.pe.</p>
  <p>&nbsp;</p>
  <p>Por tu seguridad, Mibanco te recuerda que:&nbsp;</p>
  <ul>
  <li aria-level="1">Se te enviar&aacute; una clave de 5 d&iacute;gitos (clave OTP) al n&uacute;mero de celular que tengamos consignado por ti en nuestros sistemas para confirmar que deseas cambiar tu correo electr&oacute;nico.</li>
  <li aria-level="1">Nunca solicitaremos tus datos confidenciales por correo, tales como la clave SMS de Internet, DNI o tu n&uacute;mero de celular.&nbsp;</li>
  <li aria-level="1">Para cualquier otra consulta, visita nuestra web: www.mibanco.com.pe o llama a nuestra Banca por Tel&eacute;fono al 319-9999.</li>
  </ul>
  <p><br /><br /></p>`,

  termsmodal_lpdp:
    'El solicitante/cliente autoriza a Mibanco a incorporar sus datos personales en el “Banco de Datos Personales de Usuarios” de responsabilidad de Mibanco, para almacenarlos, procesarlos, transferirlos a las empresas del Grupo Credicorp y/o socios comerciales que se indiquen en el tiempo en www.mibanco.com.pe y/o darles cualquier otra forma de tratamiento regulada por la Ley N°29733 - Ley de Protección de Datos Personales, hasta por diez (10) años después de finalizada la relación contractual. El solicitante/cliente conoce que debe comunicar cualquier actualización de su información y puede acceder a sus datos, rectificarlos, oponerse a su uso o revocar el consentimiento en cualesquiera de las agencias a nivel nacional, a través de Banca por Internet o vía Banca por Teléfono; siempre y cuando cumpla con los requisitos exigidos por la Ley. Para mayor información consultar la Políticas de Privacidad y Protección de datos publicada en www.mibanco.com.pe.',
